/**
 * qrcode.js helper using Google Chart API / QR Server fallback or Canvas QR generator
 */
function generateQRCode(elementId, text, width = 200, height = 200) {
    const container = document.getElementById(elementId);
    if (!container) return;
    container.innerHTML = '';
    
    const img = document.createElement('img');
    const encodedText = encodeURIComponent(text);
    img.src = `https://api.qrserver.com/v1/create-qr-code/?size=${width}x${height}&data=${encodedText}`;
    img.alt = 'QR Code Encrypted';
    img.width = width;
    img.height = height;
    img.style.border = '2px solid #111111';
    img.style.borderRadius = '8px';
    img.style.padding = '8px';
    img.style.backgroundColor = '#FFFFFF';
    
    container.appendChild(img);
}
